  - tools.openchamber({
  /** OpenChamber action to perform */
  action: ("projects.list" | "models.list" | "models.search" | "session.list" | "session.create" | "session.send" | "session.fork" | "session.status" | "session.messages" | "session.moveToWorktree" | "session.link" | "work.name" | "file.open") & string,
  /** Inputs for the action; use an empty object when none are needed */
  parameters?: {
    /** Not with directory */
    projectId?: string,
    /** Absolute path; default: this session's directory */
    directory?: string,
    sessionId?: string,
    /** Fork boundary */
    messageId?: string,
    link?: {
      url: string,
      title: string,
      /** change: pull, merge or change request. issue: task or ticket */
      kind: "change" | "issue",
      /** Short label such as !42 or OPS-7 */
      identifier?: string,
    },
    title?: string,
    prompt?: string,
    /**
     * provider/model. session.create with an agent and no model runs that agent's bound model; with neither, it picks from models.list favorites or recents, or omits it; send and fork omit it to keep the session's model
     */
    model?: string,
    /** Only when the user asks. Default: build for a new session, unchanged for an existing one */
    agent?: string,
    /** Only when the user asks */
    variant?: string,
    /**
     * Folder name of a new worktree, named after the task (fix-login-timeout). Required for session.moveToWorktree; on session.create only when the user asks, and uncommitted changes stay behind
     */
    worktree?: string,
    /** session.create: default the worktree name. work.name: the new name of a placeholder branch */
    branch?: string,
    /** Ref the new branch starts from; default: the repository's default branch */
    startRef?: string,
    /** Files you changed whose uncommitted changes move along; nothing else moves */
    carry?: Array<string>,
    /**
     * Check out this existing local or remote branch (origin/feature) instead of a new one; not with branch or startRef
     */
    existingBranch?: string,
    /** Track the upstream branch */
    setUpstream?: boolean,
    /**
     * session.create only, when the user asks to work on that pull or merge request: the session starts in a new worktree on its branch. worktree and branch then only rename the folder and local branch
     * @integer @minimum 1
     */
    pullRequest?: number,
    /** Goal Mode; only when the user asks */
    goal?: boolean,
    /** Requires goal. @integer @minimum 1000 @maximum 100000000 */
    goalTokenBudget?: number,
    /**
     * create, send or fork with a prompt: the final answer arrives here as a message when the session finishes. Only when the user wants the outcome or your next step needs it
     */
    returnResult?: boolean,
    /** Only the last assistant message */
    lastAssistant?: boolean,
    /** Default 10. @integer @minimum 1 */
    limit?: number,
    /** Include archived sessions, all messages, or older model versions */
    all?: boolean,
    /** Words to match in model names and ids */
    query?: string,
    /** Provider id or name */
    provider?: string,
    /** Results to skip, for the next page. @integer @minimum 0 */
    offset?: number,
    /** Only the last matching message */
    last?: boolean,
    withStatus?: boolean,
    role?: "all" | "user" | "assistant",
    /** Absolute, or relative to the session directory */
    path?: string,
  },
}): Promise<string | null> // OpenChamber projects, sessions and worktrees. One action per call; projectId or directory scope it, default this sess...
